<?php
final class EventController {
 public static function index(): void { $q=trim($_GET['q']??'');$cat=(int)($_GET['category']??0);$sql="SELECT e.*,c.name category_name,u.name organizer_name FROM events e LEFT JOIN categories c ON c.id=e.category_id LEFT JOIN users u ON u.id=e.organizer_id WHERE e.status='published' AND e.start_date>=NOW()";$args=[];if($q!==''){$sql.=' AND (e.title LIKE ? OR e.city LIKE ?)';$args[]="%$q%";$args[]="%$q%";}if($cat){$sql.=' AND e.category_id=?';$args[]=$cat;}$sql.=' ORDER BY e.start_date ASC';$s=db()->prepare($sql);$s->execute($args);$events=$s->fetchAll();$categories=db()->query('SELECT * FROM categories ORDER BY name')->fetchAll();require dirname(__DIR__,2).'/views/public/events.php'; }
 public static function detail(string $slug): void { $s=db()->prepare("SELECT e.*,c.name category_name,u.name organizer_name FROM events e LEFT JOIN categories c ON c.id=e.category_id LEFT JOIN users u ON u.id=e.organizer_id WHERE e.slug=? AND e.status='published'");$s->execute([$slug]);$event=$s->fetch();if(!$event){http_response_code(404);exit('Event tidak ditemukan');}require dirname(__DIR__,2).'/views/public/detail.php'; }
 public static function register(int $id): void { require_role('user');verify_csrf();$pdo=db();$pdo->beginTransaction();try{$s=$pdo->prepare("SELECT * FROM events WHERE id=? AND status='published' FOR UPDATE");$s->execute([$id]);$event=$s->fetch();if(!$event)throw new RuntimeException('Event tidak tersedia.');$s=$pdo->prepare('SELECT id,quota,price FROM ticket_types WHERE event_id=? AND is_active=1 ORDER BY price LIMIT 1 FOR UPDATE');$s->execute([$id]);$ticket=$s->fetch();if(!$ticket||$ticket['quota']<1)throw new RuntimeException('Tiket tidak tersedia.');$orderNo='BTV-'.date('ymd').'-'.strtoupper(bin2hex(random_bytes(3)));$s=$pdo->prepare("INSERT INTO orders(user_id,order_number,total_amount,status,expires_at,created_at) VALUES(?,?,?,'pending',DATE_ADD(NOW(),INTERVAL 30 MINUTE),NOW())");$s->execute([user()['id'],$orderNo,$ticket['price']]);$orderId=(int)$pdo->lastInsertId();$pdo->prepare('INSERT INTO order_items(order_id,ticket_type_id,quantity,unit_price,subtotal) VALUES(?,?,1,?,?)')->execute([$orderId,$ticket['id'],$ticket['price'],$ticket['price']]);$pdo->prepare("INSERT INTO payments(order_id,method,status,amount,reference,created_at) VALUES(?,?,'pending',?,?,NOW())")->execute([$orderId,'ewallet',$ticket['price'],'PAY-'.strtoupper(bin2hex(random_bytes(5)))]);$pdo->prepare('UPDATE ticket_types SET quota=quota-1 WHERE id=?')->execute([$ticket['id']]);$pdo->commit();flash('success','Pesanan dibuat. Silakan selesaikan simulasi pembayaran.');redirect('user/orders');}catch(Throwable $e){$pdo->rollBack();flash('error',$e->getMessage());redirect('events');} }
}
